<?php
declare(strict_types=1);namespace App\Interfaces\Http\Controllers\Api\V1;
use App\Application\Payments\WebhookProcessingService;use Illuminate\Http\{JsonResponse,Request};
final class PaymentWebhookController{public function __invoke(Request$r,string$provider,WebhookProcessingService$s):JsonResponse{abort_unless(in_array($provider,['fake','maviance','campay'],true),404);$event=(string)$r->header('X-Provider-Event-Id');abort_if($event==='',400,'Missing provider event identifier.');$s->verify($provider,$r->getContent(),(int)$r->header('X-Webhook-Timestamp',0),(string)$r->header('X-Signature'));$payload=$r->validate(['payment_reference'=>'required|string|max:160','status'=>'required|in:PROCESSING,SUCCEEDED,FAILED,EXPIRED,REFUNDED,CHARGED_BACK','amount_minor'=>'required|integer|min:0','currency'=>'required|in:XAF']);$s->process($provider,$event,$payload,(string)$r->header('X-Signature'));return response()->json(['accepted'=>true],202);}}
